async function seed() {
  console.log(`Seeding ${CREATURES.length} creatures...`);
  // Insert in batches to avoid hitting request size limits.
  const BATCH_SIZE = 100;
  for (let i = 0; i < CREATURES.length; i += BATCH_SIZE) {
    const batch = CREATURES.slice(i, i + BATCH_SIZE);
    const { error } = await supabase
      .from("creatures")
      .upsert(batch, { onConflict: "name", ignoreDuplicates: true });
    if (error) {
      console.error(`Batch ${i / BATCH_SIZE + 1} failed:`, error.message);
      process.exit(1);
    }
    console.log(`Seeded ${Math.min(i + BATCH_SIZE, CREATURES.length)} / ${CREATURES.length}`);
  }
  console.log("Done.");
}

seed();
